package com.CodeSphere.backend.service.impl;
import com.CodeSphere.backend.model.UserNotification; import com.CodeSphere.backend.repository.UserNotificationRepository; import com.CodeSphere.backend.service.NotificationService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.List;
@Service @RequiredArgsConstructor @Transactional public class NotificationServiceImpl implements NotificationService { private final UserNotificationRepository repository; public void notify(Long userId,String title,String message){repository.save(UserNotification.builder().userId(userId).title(title).message(message).read(false).createdAt(OffsetDateTime.now()).build());} @Transactional(readOnly=true) public List<UserNotification> mine(Long userId){return repository.findByUserIdOrderByCreatedAtDesc(userId);} public void markRead(Long userId,Long id){var n=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Notification not found"));if(!n.getUserId().equals(userId))throw new IllegalStateException("Notification is not available");n.setRead(true);} public void markAllRead(Long userId){repository.findByUserIdAndReadFalseOrderByCreatedAtDesc(userId).forEach(n->n.setRead(true));} }
